    14→// ==================== 设备码生成工具 ====================
    15→const P1 = 9857;
    16→const A1 = 1337;
    17→const P2 = 8191;
    18→const S1 = 2048;
    19→const CHAR_MAP = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
    20→const BASE = CHAR_MAP.length;
    21→
    22→function encodeNumber(num) {
    23→  if (num === 0) return '2222-2222-2222';
    24→  let result = '';
    25→  let tempNum = num;
    26→  while (tempNum > 0) {
    27→    result = CHAR_MAP[tempNum % BASE] + result;
    28→    tempNum = Math.floor(tempNum / BASE);
    29→  }
    30→  while (result.length < 12) {
    31→    result = '2' + result;
    32→  }
    33→  return `${result.substring(0, 4)}-${result.substring(4, 8)}-${result.substring(8, 12)}`;
    34→}
    35→
    36→function generateDeviceId(serialNumber) {
    37→  let result = serialNumber;
    38→  result = (result * P1) + A1;
    39→  result = (result * P2) - S1;
    40→  return encodeNumber(result);
    41→}
    42→
    43→function normalizeDeviceCode(code) {
    44→  return String(code || '').trim().toUpperCase().replace(/[-/\s]/g, '');
    45→}
    46→
    47→function maskDeviceCode(code) {
    48→  const norm = normalizeDeviceCode(code);
    49→  if (norm.length !== 12) return norm;
    50→  return `${norm.slice(0, 4)}...${norm.slice(8)}`;
    51→}
