     1→import { writeFileSync, readFileSync, rmSync } from "@zos/fs";
     2→import { log as Logger } from "@zos/utils";
     3→
     4→const log = Logger.getLogger("storage-util");
     5→
     6→export const Storage = {
     7→  /**
     8→   * Synchronously writes data to a JSON file.
     9→   * @param {string} file - The name of the file.
    10→   * @param {object} data - The data to write.
    11→   * @param {function} [callback] - Optional callback function.
    12→   */
    13→  set(file, data, callback) {
    14→    try {
    15→      if (data === null) {
    16→        rmSync(file);
    17→      } else {
    18→        const jsonStr = JSON.stringify(data);
    19→        writeFileSync({
    20→          path: file,
    21→          data: jsonStr,
    22→          options: { encoding: 'utf8' }
    23→        });
    24→      }
    25→      if (callback) callback(null, true);
    26→    } catch (err) {
    27→      log.error(`Error writing ${file}: ${err}`);
    28→      if (callback) callback(err, false);
    29→    }
    30→  },
    31→
    32→  /**
    33→   * Synchronously reads data from a JSON file.
    34→   * @param {string} file - The name of the file.
    35→   * @param {function} callback - The callback function.
    36→   */
    37→  get(file, callback) {
    38→    try {
    39→      const content = readFileSync({
    40→        path: file,
    41→        options: { encoding: 'utf8' }
    42→      });
    43→
    44→      if (content === undefined || content === null) {
    45→        return callback(null, null);
    46→      }
    47→
    48→      const data = JSON.parse(content);
    49→      callback(null, data);
    50→    } catch (err) {
    51→      callback(null, null);
    52→    }
    53→  },
    54→
    55→  /**
    56→   * Patch a JSON object file with new fields.
    57→   * Useful for categorized storage files.
    58→   * @param {string} file - The name of the file.
    59→   * @param {object} patchData - Data to merge.
    60→   * @param {function} [callback] - Optional callback function.
    61→   */
    62→  patch(file, patchData, callback) {
    63→    this.get(file, (err, currentData) => {
    64→      const newData = { ...(currentData || {}), ...patchData };
    65→      this.set(file, newData, callback);
    66→    });
    67→  },
    68→
    69→  /**
    70→   * Get a specific field from a JSON object file.
    71→   * @param {string} file - The name of the file.
    72→   * @param {string} field - The field name.
    73→   * @param {function} callback - The callback function.
    74→   */
    75→  getField(file, field, callback) {
    76→    this.get(file, (err, data) => {
    77→      if (data && typeof data === 'object') {
    78→        callback(null, data[field]);
    79→      } else {
    80→        callback(null, null);
    81→      }
    82→    });
    83→  },
    84→
    85→  /**
    86→   * Delete a file synchronously.
    87→   * @param {string} file 
    88→   */
    89→  remove(file) {
    90→    try {
    91→      rmSync(file);
    92→    } catch (e) {}
    93→  },
    94→
    95→  saveAndQuit() {
    96→    // Kept for compatibility, native FS is synchronous.
    97→  }
    98→};
