   405→    this.state.startBtn.setProperty(prop.VISIBLE, false);
   406→
   407→    let rem = DURATION_SEC;
   408→    let animAngle = 60;
   409→
   410→    this.state.ringTimer = setInterval(() => {
   411→      const target = (rem / DURATION_SEC) * 360;
   412→      animAngle += (target - animAngle) * 0.12;
   413→      this.state.ringWidget.setProperty(prop.MORE, { start_angle: 0, end_angle: Math.max(0, animAngle) });
   414→    }, 50);
   415→
   416→    const tick = () => {
   417→      const m = Math.floor(rem / 60), s = rem % 60;
   418→      this.state.countdownText.setProperty(prop.TEXT, m + ':' + s.toString().padStart(2, '0'));
   419→      
   420→      // 在 DEBUG_MODE 下，直接显示虚拟心率数据
