   422→      if (DEBUG_MODE) {
   423→        displayBpm = VIRTUAL_HR_DATA[Math.floor((DURATION_SEC - rem) / (DURATION_SEC / VIRTUAL_HR_DATA.length)) % VIRTUAL_HR_DATA.length];
   424→      } else {
