   426→      }
   427→
   428→      if (displayBpm > 0) this.state.bpmText.setProperty(prop.TEXT, 'BPM: ' + displayBpm);
   429→    };
   430→    tick();
   431→    this.state.countdownTimer = setInterval(() => {
   432→      rem--;
   433→      tick();
   434→      if (rem <= 0) this.finish();
   435→    }, 1000);
   436→
   437→    this.state.hrvCalc.start();
