   450→      setTimeout(() => { replace({ url: "page/stress_UI2" }); }, 1500);
   451→      return;
   452→    }
   453→
   454→    const { sdann, stressVal, sleepScore, hrReserve, restingHr } = this.state.allDay;
   455→    const rr = this.state.hrvCalc.rrIntervals;
   456→    const tcm = calcTcmMetrics(rr) || {};
   457→    // RSA 迷走张力：基于本次采集的自主呼吸 BPM 序列
   458→    const rsaEiRatio = calcRsaEiRatio(this.state.hrvCalc.bpmBuffer);
   459→
