   472→        sdnnSegments: tcm.sdnnSegments || [],
   473→        sleepScore,
   474→        hrReserve,
   475→        rrCount: tcm.rrCount || 0,
   476→        rsaEiRatio,
   477→      },
   478→      timestamp: Date.now()
   479→    };
   480→
   481→    logger.log(`[HRV] Record to save: ${JSON.stringify(record)}`);
   482→
   483→    this.state.hrvStorage.addRecord(record, () => {
   484→      logger.log("[HRV] 数据已保存到今日文件");
   485→      this.state.countdownText.setProperty(prop.TEXT, getText('measurement_complete'));
   486→      setTimeout(() => {
   487→        replace({ url: "page/stress_UI2" });
   488→      }, 1200);
   489→    });
