   493→    if (this.state.clockTimer) clearInterval(this.state.clockTimer);
   494→    if (this.state.countdownTimer) clearInterval(this.state.countdownTimer);
   495→    if (this.state.ringTimer) clearInterval(this.state.ringTimer);
   496→    this.state.hrvCalc.stop();
   497→    setPageBrightTime({ brightTime: -1 });
   498→    Storage.saveAndQuit();
