    50→// ratios: 长度 n 的 0~1 数组；传 null 则画满格（网格参考多边形）
    51→// 返回 n 个顶点坐标数组（未闭合），供 Canvas strokePoly / drawPoly 使用
    52→function _radarPts(cx, cy, R, n, ratios) {
    53→  var pts = [];
    54→  for (var i = 0; i < n; i++) {
    55→    var ang = (-90 + i * (360 / n)) * Math.PI / 180;
    56→    var r = R * (ratios ? Math.max(0.06, Math.min(1, ratios[i])) : 1);
    57→    pts.push({ x: Math.round(cx + r * Math.cos(ang)), y: Math.round(cy + r * Math.sin(ang)) });
    58→  }
    59→  return pts;
    60→}
