   169→  // 简易实现：通过求移动平均的差值来模拟频段分离
   170→  calculateBandRMS(bpmSeq) {
   171→    if (bpmSeq.length < 30) return { lfRms: 0, vlfRms: 0 };
   172→    
   173→    // VLF (<0.04Hz): 用极长窗口(25秒)移动平均代表极低频基线
   174→    const vlfWindow = 25;
   175→    const vlfBaseline = [];
   176→    for(let i=0; i<bpmSeq.length; i++) {
   177→      let sum = 0, count = 0;
   178→      for(let j=Math.max(0, i-vlfWindow); j<=Math.min(bpmSeq.length-1, i+vlfWindow); j++) {
   179→        sum += bpmSeq[j]; count++;
   180→      }
   181→      vlfBaseline.push(sum/count);
   182→    }
   183→    
   184→    // LF (0.04-0.15Hz): 用较短窗口(7秒)移动平均减去 VLF 基线
   185→    const lfWindow = 7;
   186→    const lfSignal = [];
   187→    for(let i=0; i<bpmSeq.length; i++) {
   188→      let sum = 0, count = 0;
   189→      for(let j=Math.max(0, i-lfWindow); j<=Math.min(bpmSeq.length-1, i+lfWindow); j++) {
   190→        sum += bpmSeq[j]; count++;
   191→      }
   192→      lfSignal.push((sum/count) - vlfBaseline[i]);
   193→    }
   194→    
   195→    // 计算 RMS
   196→    const lfRms = Math.sqrt(lfSignal.reduce((s, v) => s + v*v, 0) / lfSignal.length);
   197→    // VLF 波动是相对于整体均值的
   198→    const globalMean = bpmSeq.reduce((a,b)=>a+b,0)/bpmSeq.length;
   199→    const vlfRms = Math.sqrt(vlfBaseline.reduce((s, v) => s + Math.pow(v-globalMean, 2), 0) / vlfBaseline.length);
   200→    
   201→    return { lfRms, vlfRms };
   202→  }
   203→
   204→  getHrvMetrics() {
   205→    if (this.rrIntervals.length < 10) return null;
   206→    const rr = this.rrIntervals;
   207→    const meanRR = this.calculateMeanRR(rr);
   208→    const sdnn = this.calculateSDNN(rr);
   209→    const meanHR = meanRR != null ? 60000 / meanRR : null;
   210→    
   211→    // 计算符号熵
   212→    const patternEntropy = this.calculatePatternEntropy(this.bpmBuffer);
   213→    
   214→    // 计算 LF/VLF RMS
   215→    const { lfRms, vlfRms } = this.calculateBandRMS(this.bpmBuffer);
   216→
   217→    return {
   218→      sdnn: sdnn != null ? +sdnn.toFixed(2) : null,
   219→      mean_rr: meanRR != null ? +meanRR.toFixed(2) : null,
   220→      mean_hr: meanHR != null ? +meanHR.toFixed(1) : null,
   221→      patternEntropy: +patternEntropy.toFixed(3),
   222→      lfRms: +lfRms.toFixed(2),
   223→      vlfRms: +vlfRms.toFixed(2)
   224→    };
   225→  }
   226→}
