    38→    damp_heat:       { name: getText('const_name_damp_heat'),       desc: getText('const_desc_damp_heat') },
    39→    allergic:        { name: getText('const_name_allergic'),        desc: getText('const_desc_allergic') },
    40→  };
    41→}
