    43→// ============================================================================
    44→// 分类器 — label 通过 getText 获取
    45→// ============================================================================
    46→function classifyRate(restingHr) {
    47→  if (restingHr <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
    48→  if (restingHr < 52) return { value: restingHr, category: 'chi',   label: getText('dim_label_rate_chi'),   score: 2 };
    49→  if (restingHr < 62) return { value: restingHr, category: 'huan',  label: getText('dim_label_rate_huan'),  score: 7 };
    50→  if (restingHr < 78) return { value: restingHr, category: 'zhong', label: getText('dim_label_rate_zhong'), score: 8 };
    51→  if (restingHr < 90) return { value: restingHr, category: 'pian_shuo', label: getText('dim_label_rate_pian_shuo'), score: 5 };
    52→  return { value: restingHr, category: 'shuo', label: getText('dim_label_rate_shuo'), score: 3 };
    53→}
    54→
    55→function classifyRhythm(sdnn) {
    56→  if (sdnn <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
    57→  if (sdnn < 18) return { value: sdnn, category: 'jie_dai',   label: getText('dim_label_rhythm_jie_dai'),   score: 2 };
    58→  if (sdnn < 30) return { value: sdnn, category: 'pian_buqi', label: getText('dim_label_rhythm_pian_buqi'), score: 4 };
    59→  if (sdnn < 50) return { value: sdnn, category: 'ke',        label: getText('dim_label_rhythm_ke'),        score: 6 };
    60→  if (sdnn < 75) return { value: sdnn, category: 'qi',        label: getText('dim_label_rhythm_qi'),        score: 8 };
    61→  return { value: sdnn, category: 'he', label: getText('dim_label_rhythm_he'), score: 9 };
    62→}
    63→
    64→function classifyStrength(sdann, hrReserve) {
    65→  if (sdann <= 0 && hrReserve <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
    66→  const score = (sdann > 0 ? Math.min(1, sdann / 80) : 0.5) * 0.6 + (hrReserve > 0 ? Math.min(1, hrReserve / 60) : 0.5) * 0.4;
    67→  if (score < 0.2)  return { value: score, category: 'xu',       label: getText('dim_label_strength_xu'),       score: 2 };
    68→  if (score < 0.35) return { value: score, category: 'pian_xu',  label: getText('dim_label_strength_pian_xu'),  score: 4 };
    69→  if (score < 0.55) return { value: score, category: 'ping',     label: getText('dim_label_ping'),              score: 6 };
    70→  if (score < 0.75) return { value: score, category: 'pian_shi', label: getText('dim_label_strength_pian_shi'), score: 7 };
    71→  return { value: score, category: 'shi', label: getText('dim_label_strength_shi'), score: 9 };
    72→}
    73→
    74→function classifyWidth(hrStability, stress) {
    75→  if (hrStability <= 0 && stress <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
    76→  const s = (stress > 0 ? 1 - Math.min(1, stress / 100) : 0.5) * 0.5 + (hrStability > 0 ? Math.min(1, hrStability / 15) : 0.5) * 0.5;
    77→  if (s < 0.25) return { value: s, category: 'xi',        label: getText('dim_label_width_xi'),        score: 3 };
    78→  if (s < 0.4)  return { value: s, category: 'pian_xi',   label: getText('dim_label_width_pian_xi'),   score: 4 };
    79→  if (s < 0.6)  return { value: s, category: 'ping',      label: getText('dim_label_ping'),             score: 7 };
    80→  if (s < 0.8)  return { value: s, category: 'pian_hong', label: getText('dim_label_width_pian_hong'), score: 8 };
    81→  return { value: s, category: 'hong', label: getText('dim_label_width_hong'), score: 9 };
    82→}
    83→
    84→function classifyTension(stress, sdnn) {
    85→  if (stress <= 0 && sdnn <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
    86→  const t = (stress > 0 ? Math.min(1, stress / 100) : 0.5) * 0.6 + (sdnn > 0 ? 1 - Math.min(1, sdnn / 100) : 0.5) * 0.4;
    87→  if (t < 0.2)  return { value: t, category: 'ruan',       label: getText('dim_label_tension_ruan'),       score: 3 };
    88→  if (t < 0.35) return { value: t, category: 'ru',         label: getText('dim_label_tension_ru'),         score: 5 };
    89→  if (t < 0.5)  return { value: t, category: 'ping',       label: getText('dim_label_ping'),               score: 7 };
    90→  if (t < 0.7)  return { value: t, category: 'pian_xian',  label: getText('dim_label_tension_pian_xian'),  score: 4 };
    91→  return { value: t, category: 'xian', label: getText('dim_label_tension_xian'), score: 2 };
    92→}
