    97→function organDescKey(organ, status) {
    98→  const map = {
    99→    '心': { '和': 'organ_desc_heart_he', '平': 'organ_desc_heart_ping', '虚': 'organ_desc_heart_xu', '亏': 'organ_desc_heart_kui' },
   100→    '肝': { '和': 'organ_desc_liver_he', '平': 'organ_desc_liver_ping', '虚': 'organ_desc_liver_xu', '亏': 'organ_desc_liver_kui' },
   101→    '脾': { '和': 'organ_desc_spleen_he', '平': 'organ_desc_spleen_ping', '虚': 'organ_desc_spleen_xu', '亏': 'organ_desc_spleen_kui' },
   102→    '肺': { '和': 'organ_desc_lung_he', '平': 'organ_desc_lung_ping', '虚': 'organ_desc_lung_xu', '亏': 'organ_desc_lung_kui' },
   103→    '肾': { '和': 'organ_desc_kidney_he', '平': 'organ_desc_kidney_ping', '虚': 'organ_desc_kidney_xu', '亏': 'organ_desc_kidney_kui' },
   104→  };
   105→  return map[organ]?.[status] || '';
   106→}
