   108→// ============================================================================
   109→// 主脉象匹配
   110→// ============================================================================
   111→function matchPulseType(dimensions, metrics) {
   112→  const { restingHr, sdnn, sdann, stress, hrStability, hrReserve } = metrics;
   113→  const scores = {};
   114→  scores.fu   = (stress > 50 ? 0.7 : stress / 70) * 0.5 + (restingHr > 70 ? 0.6 : 0.3) * 0.3 + 0.2;
   115→  scores.chen = (stress < 30 ? 0.8 : (100 - stress) / 125) * 0.4 + (restingHr < 60 ? 0.7 : 0.3) * 0.3 + (sdann < 40 ? 0.7 : 0.3) * 0.3;
   116→  scores.chi  = restingHr < 55 ? (55 - restingHr) / 20 + 0.3 : 0.2;
   117→  scores.shuo = restingHr > 85 ? (restingHr - 85) / 20 + 0.3 : 0.2;
   118→  scores.hua  = Math.min(1, sdnn / 100) * 0.5 + Math.min(1, sdann / 80) * 0.5;
   119→  scores.se   = (1 - Math.min(1, sdnn / 60)) * 0.6 + Math.min(1, stress / 100) * 0.4;
   120→  scores.xu   = (1 - Math.min(1, sdnn / 80)) * 0.4 + (1 - Math.min(1, sdann / 70)) * 0.3 + (1 - Math.min(1, hrReserve / 50)) * 0.3;
   121→  scores.shi  = Math.min(1, sdnn / 80) * 0.4 + Math.min(1, sdann / 70) * 0.3 + Math.min(1, hrReserve / 50) * 0.3;
   122→  scores.xian = Math.min(1, stress / 100) * 0.5 + (1 - Math.min(1, sdnn / 80)) * 0.3 + (restingHr > 60 ? 0.4 : 0.1) * 0.2;
   123→  scores.xi   = (1 - Math.min(1, sdnn / 60)) * 0.4 + (restingHr < 65 ? 0.5 : 0.2) * 0.3 + (1 - Math.min(1, sdann / 60)) * 0.3;
   124→  scores.hong = Math.min(1, sdann / 80) * 0.5 + Math.min(1, hrReserve / 70) * 0.5;
   125→  scores.huan = (restingHr >= 55 && restingHr <= 75 ? 0.8 : 0.2) * 0.35 + (sdnn >= 35 && sdnn <= 70 ? 0.8 : 0.2) * 0.35 + (stress < 50 ? 0.6 : 0.2) * 0.3;
   126→  scores.jie  = sdnn < 20 ? (20 - sdnn) / 20 + 0.2 : 0.1;
   127→  scores.dai  = sdnn < 22 ? (22 - sdnn) / 22 + 0.15 : 0.1;
   128→
   129→  // RSA 维度修正：刚性=弦/涩脉加分，灵活=滑/平脉加分
   130→  if (dimensions.rsa && dimensions.rsa.category !== 'unknown') {
   131→    const rsaScore = dimensions.rsa.score / 9;
   132→    if (dimensions.rsa.category === 'rigid' || dimensions.rsa.category === 'blunted') {
   133→      scores.xian += rsaScore * 0.15;
   134→      scores.se   += rsaScore * 0.10;
   135→    } else {
   136→      scores.hua  += rsaScore * 0.15;
   137→      scores.huan += rsaScore * 0.10;
   138→    }
   139→  }
   140→
   141→  const maxScore = Math.max(...Object.values(scores), 0.01);
   142→  Object.keys(scores).forEach(k => { scores[k] = Math.min(1, scores[k] / maxScore); });
   143→
   144→  let bestType = 'huan', bestScore = 0;
   145→  Object.entries(scores).forEach(([type, score]) => { if (score > bestScore) { bestScore = score; bestType = type; } });
   146→
   147→  const PULSE_TYPES = resolvePulseTypes();
   148→  const info = PULSE_TYPES[bestType];
   149→  return { type: bestType, name: info.name, description: info.desc, nature: info.nature, confidence: Math.round(bestScore * 100) / 100, allScores: scores };
   150→}
