   152→// ============================================================================
   153→// 体质判定
   154→// ============================================================================
   155→function assessConstitution(dimensions, mainPulse, metrics) {
   156→  const { stress, sdnn, restingHr } = metrics;
   157→  const scores = {};
   158→  scores.balanced = dimensions.rate.score >= 6 && dimensions.rhythm.score >= 6 && dimensions.strength.score >= 5 && dimensions.tension.score >= 4 ? 0.8 : 0.2;
   159→  scores.qi_deficiency   = (1 - Math.min(1, sdnn / 60)) * 0.5 + (1 - Math.min(1, dimensions.strength.score / 9)) * 0.5;
   160→  scores.yang_deficiency = (restingHr < 58 ? 0.6 : 0.2) * 0.5 + (1 - Math.min(1, dimensions.strength.score / 9)) * 0.5;
   161→  scores.yin_deficiency  = (restingHr > 78 ? 0.6 : 0.2) * 0.5 + Math.min(1, stress / 100) * 0.5;
   162→  scores.qi_stagnation   = Math.min(1, stress / 80) * 0.5 + (1 - Math.min(1, sdnn / 70)) * 0.25 + (dimensions.tension.category === 'xian' || dimensions.tension.category === 'pian_xian' ? 0.7 : 0.2) * 0.25;
   163→  scores.blood_stasis    = (1 - Math.min(1, sdnn / 50)) * 0.5 + (dimensions.tension.category === 'xian' ? 0.6 : 0.2) * 0.3 + (mainPulse.type === 'se' || mainPulse.type === 'jie' ? 0.5 : 0.1) * 0.2;
   164→  scores.phlegm_damp     = (1 - Math.min(1, sdnn / 65)) * 0.4 + (dimensions.width.category === 'hong' || dimensions.width.category === 'pian_hong' ? 0.6 : 0.2) * 0.6;
   165→  scores.damp_heat       = (restingHr > 72 ? 0.5 : 0.2) * 0.4 + Math.min(1, stress / 85) * 0.4 + (dimensions.strength.category === 'shi' ? 0.4 : 0.2) * 0.2;
   166→  scores.allergic        = (dimensions.rhythm.category === 'pian_buqi' || dimensions.rhythm.category === 'jie_dai' ? 0.5 : 0.15) * 0.5 + (1 - Math.min(1, sdnn / 55)) * 0.5;
   167→
   168→  const maxScore = Math.max(...Object.values(scores), 0.01);
   169→  Object.keys(scores).forEach(k => { scores[k] = Math.min(1, Math.max(0, scores[k] / maxScore)); });
   170→
   171→  let bestType = 'balanced', bestScore = 0;
   172→  Object.entries(scores).forEach(([type, score]) => { if (score > bestScore) { bestScore = score; bestType = type; } });
   173→
   174→  const CONSTITUTIONS = resolveConstitutions();
   175→  const cnst = CONSTITUTIONS[bestType];
   176→  return { type: bestType, name: cnst.name, description: cnst.desc, score: Math.round(bestScore * 100) / 100, allScores: scores };
   177→}
