   179→// ============================================================================
   180→// 五脏关联
   181→// ============================================================================
   182→function analyzeOrgans(dimensions, mainPulse, metrics) {
   183→  const { stress, sdnn, restingHr, sleepScore } = metrics;
   184→  const heartScore   = (dimensions.rhythm.score * 0.5 + dimensions.rate.score * 0.3 + (sleepScore || 5) / 10 * 2 * 0.2);
   185→  const liverScore   = ((10 - dimensions.tension.score) * 0.4 + (stress > 50 ? (100 - stress) / 50 : 8) * 0.4 + dimensions.rate.score * 0.2);
   186→  const spleenScore  = (dimensions.width.score * 0.4 + dimensions.strength.score * 0.4 + (restingHr > 60 && restingHr < 80 ? 7 : 4) * 0.2);
   187→  const lungScore    = (dimensions.strength.score * 0.5 + dimensions.rhythm.score * 0.5);
   188→  const kidneyScore  = (dimensions.strength.score * 0.5 + (restingHr < 75 ? 7 : 4) * 0.3 + (sdnn > 35 ? 7 : 4) * 0.2);
   189→
   190→  const organs = [
   191→    { organ: getText('organ_name_heart'),  score: Math.round(heartScore * 10) / 10 },
   192→    { organ: getText('organ_name_liver'),  score: Math.round(liverScore * 10) / 10 },
   193→    { organ: getText('organ_name_spleen'), score: Math.round(spleenScore * 10) / 10 },
   194→    { organ: getText('organ_name_lung'),   score: Math.round(lungScore * 10) / 10 },
   195→    { organ: getText('organ_name_kidney'), score: Math.round(kidneyScore * 10) / 10 },
   196→  ];
   197→
   198→  organs.forEach(o => {
   199→    if (o.score >= 7)      o.status = getText('organ_status_he');
   200→    else if (o.score >= 5) o.status = getText('organ_status_ping');
   201→    else if (o.score >= 3) o.status = getText('organ_status_xu');
   202→    else                   o.status = getText('organ_status_kui');
   203→    o.desc = getText(organDescKey(o.organ, o.status));
   204→  });
   205→  return organs;
   206→}
