   236→  recs.push({ category: getText('rec_cat_rest'), advice: restAdvice.join(getText('rec_separator')) });
   237→
   238→  // 运动
   239→  const exerciseAdvice = [];
   240→  if (constitution.type === 'qi_deficiency' || constitution.type === 'yang_deficiency') {
   241→    exerciseAdvice.push(getText('rec_exercise_gentle'));
   242→  } else if (constitution.type === 'qi_stagnation' || dimensions.tension.category === 'xian') {
   243→    exerciseAdvice.push(getText('rec_exercise_cardio'));
   244→  } else {
   245→    exerciseAdvice.push(getText('rec_exercise_default'));
   246→  }
   247→  recs.push({ category: getText('rec_cat_exercise'), advice: exerciseAdvice.join(getText('rec_separator')) });
   248→
   249→  // 情志
   250→  const mindAdvice = [];
   251→  if (dimensions.tension.category === 'xian') {
   252→    mindAdvice.push(getText('rec_mind_meditate'));
   253→  } else if (constitution.type === 'qi_stagnation') {
   254→    mindAdvice.push(getText('rec_mind_social'));
