   265→// ============================================================================
   266→// 趋势分析
   267→// ============================================================================
   268→export function analyzeTrend(currentSdnn, currentSdann, historyRecords) {
   269→  if (!historyRecords || historyRecords.length < 3) {
   270→    return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   271→  }
   272→  const recent = historyRecords.slice(-7);
   273→  const sdnnValues = recent.map(r => r.metrics?.sdnn || r.sdnn || 0).filter(v => v > 0);
   274→  if (sdnnValues.length < 3) return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   275→
   276→  const avgSdnn = sdnnValues.reduce((a, b) => a + b, 0) / sdnnValues.length;
   277→  const changeRate = avgSdnn > 0 ? (currentSdnn - avgSdnn) / avgSdnn : 0;
   278→
   279→  let direction = 'stable', labelKey = 'trend_stable';
   280→  if (changeRate > 0.15)      { direction = 'improving'; labelKey = 'trend_improving'; }
   281→  else if (changeRate > 0.05) { direction = 'slightly_improving'; labelKey = 'trend_slightly_improving'; }
   282→  else if (changeRate < -0.15) { direction = 'declining'; labelKey = 'trend_declining'; }
   283→  else if (changeRate < -0.05) { direction = 'slightly_declining'; labelKey = 'trend_slightly_declining'; }
   284→  return { trend: direction, label: getText(labelKey), direction, changeRate: Math.round(changeRate * 100) / 100 };
   285→}
