   122→   */
   123→  _addToHistoryIndex(dateStr, callback) {
   124→    Storage.get(HISTORY_INDEX_FILE, (err, index) => {
   125→      let historyIndex = index || [];
   126→      if (!historyIndex.includes(dateStr)) {
   127→        historyIndex.push(dateStr);
