    97→    if (this.todayDate === todayStr && this.todayCache) {
    98→      // 缓存命中
    99→      callback();
   100→      return;
   101→    }
   102→
   103→    Storage.get(TODAY_FILE, (err, data) => {
   104→      this.todayCache = data || [];
   105→      this.todayDate = todayStr;
   106→      callback();
   107→    });
   108→  }
   109→
   110→  /**
   111→   * 加载历史索引
   112→   */
   113→  _loadHistoryIndex(callback) {
   114→    Storage.get(HISTORY_INDEX_FILE, (err, index) => {
   115→      this.historyIndex = index || [];
   116→      callback();
   117→    });
   118→  }
   119→
   120→  /**
   121→   * 添加到历史索引
   122→   */
   123→  _addToHistoryIndex(dateStr, callback) {
   124→    Storage.get(HISTORY_INDEX_FILE, (err, index) => {
   125→      let historyIndex = index || [];
   126→      if (!historyIndex.includes(dateStr)) {
   127→        historyIndex.push(dateStr);
   128→        Storage.set(HISTORY_INDEX_FILE, historyIndex, () => {
   129→          if (callback) callback();
   130→        });
   131→      } else {
   132→        if (callback) callback();
   133→      }
   134→    });
   135→  }
   136→
   137→  /**
   138→   * 添加一条 HRV 记录（总是添加到今日数据）
   139→   */
   140→  addRecord(record, callback) {
   141→    this._loadTodayData(() => {
   142→      if (!this.todayCache) {
   143→        this.todayCache = [];
   144→      }
   145→
   146→      this.todayCache.push(record);
   147→
   148→      // 保存到今日文件
   149→      Storage.set(TODAY_FILE, this.todayCache, () => {
   150→        if (callback) callback();
   151→      });
   152→    });
   153→  }
   154→
   155→  /**
   156→   * 获取今日所有数据
   157→   */
   158→  getTodayData(callback) {
   159→    this._loadTodayData(() => {
   160→      callback(this.todayCache || []);
   161→    });
   162→  }
   163→
   164→  /**
   165→   * 获取指定日期的历史数据
   166→   */
   167→  getHistoryData(dateStr, callback) {
   168→    const historyFile = this._getHistoryFileKey(dateStr);
   169→    Storage.get(historyFile, (err, data) => {
   170→      callback(data || []);
   171→    });
   172→  }
   173→
   174→  /**
   175→   * 获取所有历史日期索引
   176→   */
   177→  getHistoryIndex(callback) {
   178→    this._loadHistoryIndex(() => {
   179→      callback(this.historyIndex || []);
   180→    });
   181→  }
   182→
   183→  /**
   184→   * 获取最近 N 天的数据（跨文件查询）
   185→   */
   186→  getRecentDays(days, callback) {
   187→    const result = [];
   188→
   189→    // 先获取今日数据
   190→    this.getTodayData((todayData) => {
   191→      result.push(...todayData);
   192→
   193→      // 如果只需要今日数据，直接返回
   194→      if (days === 1) {
   195→        callback(result);
   196→        return;
   197→      }
   198→
   199→      // 从历史索引中获取最近几天的日期
   200→      this.getHistoryIndex((historyIndex) => {
   201→        const sortedHistory = historyIndex.sort((a, b) => new Date(b).getTime() - new Date(a).getTime()); // 按日期降序
   202→        let fetchedDays = 0;
   203→        let historyDataPromises = [];
   204→
   205→        // 异步获取历史数据
   206→        for (let i = 0; i < sortedHistory.length && fetchedDays < days - 1; i++) {
   207→          const dateStr = sortedHistory[i];
   208→          historyDataPromises.push(new Promise(resolve => {
   209→            this.getHistoryData(dateStr, (dayData) => {
   210→              result.push(...dayData);
   211→              fetchedDays++;
   212→              resolve();
   213→            });
   214→          }));
   215→        }
   216→
   217→        // 等待所有历史数据获取完毕
   218→        Promise.all(historyDataPromises).then(() => {
   219→          callback(result);
   220→        });
   221→      });
   222→    });
   223→  }
   224→
   225→  /**
   226→   * 清除所有历史数据（保留今日数据）
   227→   */
   228→  clearHistory(callback) {
   229→    this._loadHistoryIndex(() => {
   230→      if (!this.historyIndex || this.historyIndex.length === 0) {
   231→        if (callback) callback();
   232→        return;
   233→      }
   234→
   235→      let deletedCount = 0;
   236→      this.historyIndex.forEach((dateStr) => {
   237→        const historyFile = this._getHistoryFileKey(dateStr);
   238→        Storage.remove(historyFile); // Storage.remove 是同步的，不需要回调
   239→        deletedCount++;
   240→        if (deletedCount >= this.historyIndex.length) {
   241→          // 清空索引
   242→          Storage.set(HISTORY_INDEX_FILE, [], () => {
   243→            this.historyIndex = [];
   244→            if (callback) callback();
   245→          });
   246→        }
   247→      });
   248→    });
   249→  }
   250→
   251→  /**
   252→   * 清除今日数据
   253→   */
   254→  clearToday(callback) {
   255→    Storage.set(TODAY_FILE, [], () => {
   256→      this.todayCache = [];
   257→      if (callback) callback();
   258→    });
   259→  }
   260→
   261→  /**
   262→   * 获取存储统计信息
   263→   */
   264→  getStats(callback) {
   265→    const stats = {
   266→      todayCount: 0,
   267→      historyDays: 0,
   268→      totalRecords: 0
   269→    };
   270→
   271→    this.getTodayData((todayData) => {
   272→      stats.todayCount = todayData.length;
   273→      stats.totalRecords += todayData.length;
   274→
   275→      this.getHistoryIndex((index) => {
   276→        stats.historyDays = index.length;
   277→
   278→        // 计算历史总记录数（可选，可能需要较长时间）
   279→        let loadedCount = 0;
   280→        if (index.length === 0) {
   281→          callback(stats);
   282→          return;
   283→        }
   284→
   285→        index.forEach((dateStr) => {
   286→          this.getHistoryData(dateStr, (dayData) => {
   287→            stats.totalRecords += dayData.length;
   288→            loadedCount++;
   289→
   290→            if (loadedCount >= index.length) {
   291→              callback(stats);
   292→            }
   293→          });
   294→        });
   295→      });
   296→    });
   297→  }
   298→}
