   225→  var cardH = descY + descH + pl(18);
   226→  var cardY = arcBottomY + pl(122);
   227→
   228→  vc.createWidget(widget.FILL_RECT, {
   229→    x: cardX, y: cardY, w: cardW, h: cardH, radius: pl(24), color: C.cardBg,
   230→  }).setAlpha(220);
   231→
   232→  vc.createWidget(widget.TEXT, {
   233→    x: cardX + pad, y: cardY + titleY, w: textW, h: pl(36),
   234→    text_size: titleSize, color: item.tint,
   235→    text: name + ' · ' + label, align_h: align.LEFT,
   236→  });
   237→
   238→  vc.createWidget(widget.FILL_RECT, {
   239→    x: cardX + pad, y: cardY + sepY, w: textW, h: 2, color: C.sep,
   240→  });
   241→
   242→  if (desc) {
   243→    vc.createWidget(widget.TEXT, {
   244→      x: cardX + pad, y: cardY + descY, w: textW, h: descH,
   245→      text_size: descSize, color: C.text,
   246→      text: descText, text_style: text_style.WRAP, align_h: align.LEFT,
   247→    });
   248→  }
   249→
   250→ 
   251→
   252→  return fgArc;
   253→}
