     1→/**
     2→ * pulse_theory.js — 脉象学原理
     3→ *
     4→ * Swiper 3 屏：
     5→ *   屏1 脉诊源流（markdown 渲染 + 毛玻璃卡片，scrollable）
     6→ *   屏2 二十八脉述要（GROUP 横向滑屏，14 种脉象）
     7→ *   屏3 脉象与健康指南（markdown 渲染 + 毛玻璃卡片，scrollable）
     8→ *
     9→ * 古风配色复用 organ_showcase.js 的 C 调色板
    10→ * markdown 渲染使用 markdown-renderer 库解析 + 自定义古风颜色
    11→ *
    12→ * API_LEVEL: 3.0+
    13→ */
    14→
    15→import { createWidget, widget, align, prop, text_style, getTextLayout } from '@zos/ui';
    16→import { getDeviceInfo } from '@zos/device';
    17→import { pw, ph, pl } from '../utils/zaui';
    18→import { getText } from '@zos/i18n';
    19→import { setScrollMode, SCROLL_MODE_SWIPER_HORIZONTAL } from '@zos/page';
    20→import { setStatusBarVisible } from '@zos/ui';
    21→import { buildMarkdownLayout } from '../utils/markdown-renderer';
    22→
    23→// =============================================================================
    24→// 古风配色（浅色宣纸背景主题）
    25→// =============================================================================
    26→const C = {
    27→  gold:     0x8A5A20,  // 深金（h1 主标题）
    28→  goldSoft: 0xB8860B,  // 中金（h3 小标题）
    29→  jade:     0x4E7A88,  // 青黛（h2，浅底加深）
    30→  text:     0x5A4632,  // 深棕（正文）
    31→  dim:      0x8A6E4E,  // 墨棕（引文/次要，浅底可读）
    32→  cardBg:   0xD8CCB2,  // 宣纸卡底（配 setAlpha 毛玻璃）
    33→  frost:    0xB8A890,
    34→  arcBg:    0x3A2C1E,
    35→  sep:      0xC4B594,
    36→  accent:   0xC0A050,  // 金色饰线
    37→  dotOn:    0x8A5A20,
    38→  dotOff:   0xC6B896,
    39→};
    40→
    41→function mdColor(type) {
    42→  switch (type) {
    43→    case 'heading1': return C.gold;
    44→    case 'heading2': return C.jade;
    45→    case 'heading3': return C.goldSoft;
    46→    case 'blockquote': return C.dim;
    47→    default: return C.text;
    48→  }
    49→}
    50→
    51→// =============================================================================
    52→// 14 种脉象  /
    53→
    54→  
    55→// =============================================================================
    56→var PULSE_KEYS = [
    57→  'fu', 'chen', 'chi', 'shuo', 'hua', 'se', 'xu',
    58→  'shi', 'xian', 'xi', 'hong', 'huan', 'jie', 'dai'
    59→];
    60→
    61→var PULSE_NATURE = {
    62→  fu:'阳', chen:'阴', chi:'阴', shuo:'阳', hua:'阳', se:'阴',
    63→  xu:'阴', shi:'阳', xian:'阳', xi:'阴', hong:'阳',
    64→  huan:'平', jie:'阴', dai:'阴'
    65→};
    66→
    67→var _PW, _PH;
    68→
    69→// =============================================================================
    70→// 在 VIEW_CONTAINER 内渲染 markdown 块
    71→// 可传入预计算的 layout 避免重复解析
    72→// =============================================================================
    73→function renderMdInVC(vc, md, x, y, w, fontSize, prebuiltLayout) {
    74→  var layout = prebuiltLayout || buildMarkdownLayout(md, w, fontSize);
    75→  var cy = y;
    76→  layout.items.forEach(function (item) {
    77→    vc.createWidget(widget.TEXT, {
    78→      x: x, y: cy, w: w, h: item.height,
    79→      text: item.text,
    80→      text_size: item.style.size,
    81→      color: mdColor(item.type),
    82→      text_style: text_style.WRAP,
