+<template>
+  <!--
+    雷达图（无 canvas 复原方案）：
+    每条边/轴线 = 一个绝对定位的细长 div，经 transform: rotate 摆到两点连线上；
+    数据多边形 = 金色描边 + 中心放射柔金线（模拟填充）+ 顶点圆点。
+    与 Zepp OS 版 _radarPts/_drawRadarCard 同一套坐标算法（支持 n=5/6 任意轴数）。
+  -->
+  <div class="radar-box">
+    <div
+      class="ln"
+      for="{{ (i, l) in lines }}"
+      tid="i"
+      style="left: {{ l.x }}px; top: {{ l.y }}px; width: {{ l.len }}px; height: {{ l.t }}px; background-color: {{ l.c }}; transform: rotate({{ l.deg }}deg);"
+    ></div>
+    <div
+      class="dot"
+      for="{{ (i, d) in dots }}"
+      tid="i"
+      style="left: {{ d.x }}px; top: {{ d.y }}px;"
+    ></div>
+    <text
+      class="lb"
+      for="{{ (i, t) in labelPos }}"
+      tid="i"
+      style="left: {{ t.x }}px; top: {{ t.y }}px;"
+    >{{ t.text }}</text>
+  </div>
+</template>

+<script>
+// 盒 346x228，雷达中心 (173,114)，外接半径 80（与源版 R=pl(80) 一致）
+const W = 346, R = 80, CX = 173, CY = 114;
+const C_OUTER = '#B0A283', C_INNER = '#CBBD9C', C_AXIS = '#CBBD9C';
+const C_DATA = '#C09040', C_SPOKE = '#E6C878';
+
+export default {
+  props: ['labels', 'ratios'],
+
+  data() {
+    return { lines: [], dots: [], labelPos: [] };
+  },
+
+  onInit() {
+    this._build();
+  },
+
+  // 顶点坐标：-90° 起顺时针均分；ratios 为 null 画满格（网格参考多边形）
+  _pts(n, r, ratios) {
+    const pts = [];
+    for (let i = 0; i < n; i++) {
+      const ang = (-90 + i * (360 / n)) * Math.PI / 180;
+      const rr = r * (ratios ? Math.max(0.06, Math.min(1, ratios[i])) : 1);
+      pts.push({ x: CX + rr * Math.cos(ang), y: CY + rr * Math.sin(ang) });
+    }
+    return pts;
+  },
+
+  // 两点连线 → 旋转细长条参数
+  _seg(p1, p2, t, c, out) {
+    const dx = p2.x - p1.x, dy = p2.y - p1.y;
+    const len = Math.sqrt(dx * dx + dy * dy);
+    if (len < 1) return;
+    const deg = Math.atan2(dy, dx) * 180 / Math.PI;
+    out.push({
+      x: Math.round((p1.x + p2.x) / 2 - len / 2),
+      y: Math.round((p1.y + p2.y) / 2 - t / 2),
+      len: Math.round(len),
+      t, c,
+      deg: Math.round(deg)
+    });
+  },
+
+  _build() {
+    const labels = this.labels || [];
+    const n = labels.length;
+    if (n < 3) return;
+    const ratios = (this.ratios && this.ratios.length === n) ? this.ratios : null;
+    const lines = [], dots = [], labelPos = [];
+    const center = { x: CX, y: CY };
+
+    // 网格：外框 + 0.5R 内环 + 放射轴线
+    const outer = this._pts(n, R, null);
+    const inner = this._pts(n, R * 0.5, null);
+    for (let i = 0; i < n; i++) {
+      this._seg(outer[i], outer[(i + 1) % n], 2, C_OUTER, lines);
+      this._seg(inner[i], inner[(i + 1) % n], 2, C_INNER, lines);
+      this._seg(center, outer[i], 2, C_AXIS, lines);
+    }
+
+    // 数据多边形：放射柔金线（模拟填充）+ 金色描边 + 顶点圆点
+    if (ratios) {
+      const data = this._pts(n, R, ratios);
+      for (let i = 0; i < n; i++) {
+        this._seg(center, data[i], 2, C_SPOKE, lines);
+        this._seg(data[i], data[(i + 1) % n], 3, C_DATA, lines);
+        dots.push({ x: Math.round(data[i].x) - 5, y: Math.round(data[i].y) - 5 });
+      }
+    }
+
+    // 轴标签（96px 文本盒中心对准标签点）
+    const labelR = R + 22;
+    for (let i = 0; i < n; i++) {
+      const ang = (-90 + i * (360 / n)) * Math.PI / 180;
+      labelPos.push({
+        text: labels[i],
+        x: Math.round(CX + labelR * Math.cos(ang)) - 48,
+        y: Math.round(CY + labelR * Math.sin(ang)) - 13
+      });
+    }
+
+    this.lines = lines;
+    this.dots = dots;
+    this.labelPos = labelPos;
+  }
+}
