/**
 * arc_text.js — 弧形文本排布计算
 * 屏幕设计宽 480：圆心 (240,240)，半径 210，字符沿顶部圆弧排布。
 * 计算放在页面侧、结果经 prop 传给 arc-clock 纯渲染，
 * 规避子组件 $watch prop 不触发的问题。
 */
const CX = 240, CY = 240, RADIUS = 210, STEP_DEG = 11;

export function arcChars(text) {
  const s = String(text || '');
  const n = s.length;
  if (n === 0) return [];
  const startDeg = -90 - ((n - 1) / 2) * STEP_DEG;
  const out = [];
  for (let i = 0; i < n; i++) {
    const deg = startDeg + i * STEP_DEG;
    const rad = deg * Math.PI / 180;
    out.push({
      t: s[i],
      // 40x44 文本盒中心对准弧上坐标
      x: Math.round(CX + RADIUS * Math.cos(rad)) - 20,
      y: Math.round(CY + RADIUS * Math.sin(rad)) - 22
    });
  }
  return out;
}

// 当前时间 HH:MM 的弧排字符
export function arcClockChars() {
  const n = new Date();
  const hh = String(n.getHours()).padStart(2, '0');
  const mm = String(n.getMinutes()).padStart(2, '0');
  return arcChars(hh + ':' + mm);
}

