onShow() {
  this._startClock();
  this._startWave();
  brightness.setKeepScreenOn({ keepScreenOn: true });
},

onHide() {
  brightness.setKeepScreenOn({ keepScreenOn: false });
  if (this._clockTimer) { clearInterval(this._clockTimer); this._clockTimer = null; }
  if (this._waveTimer) { clearInterval(this._waveTimer); this._waveTimer = null; }
},

onDestroy() {
  this._teardown();
  brightness.setKeepScreenOn({ keepScreenOn: false });
  if (this._clockTimer) { clearInterval(this._clockTimer); this._clockTimer = null; }
  if (this._waveTimer) { clearInterval(this._waveTimer); this._waveTimer = null; }
},

_startClock() {
  const tick = () => {
    const n = new Date();
    this.clockText = String(n.getHours()).padStart(2, '0') + ':' + String(n.getMinutes()).padStart(2, '0');
  };
  tick();
  if (!this._clockTimer) this._clockTimer = setInterval(tick, 30000);
},

// 脉波循环左移，营造"脉息流动"的活感（测量中加速）
_startWave() {
  if (this._waveTimer) return;
  this._waveTimer = setInterval(() => {
    const step = this.isMeasuring ? 10 : 5;
    this._wavePhase = (this._wavePhase + step) % this._baseWave.length;
    this._renderWave();
  }, 280);
},

_renderWave() {
  const p = this._wavePhase;
  const base = this._baseWave;
  this.waveData = [
    { strokeColor: '#C09040', data: base.slice(p).concat(base.slice(0, p)) }
  ];
},

