var healthService = require("@app-module/service.health");

// 2. 启动心率轮询定时器（每 10 秒执行一次）
function startHeartRatePolling() {
    this.updateHeartRate();
    this.heartRateTimer = setInterval(() => {
        this.updateHeartRate();
    }, 10000); // 10000ms = 10秒
}

// 3. 核心获取方法：真正调用硬件接口
function updateHeartRate() {
    try {
        // 调用底层健康服务的 getHr() 方法直接读取硬件传感器的实时心率数值
        let currentHr = healthService.default.getHr();

        // 校验：如果获取到的心率大于0（证明佩戴有效且数据正常）
        if (currentHr && currentHr > 0) {
            global.heartRate = currentHr;            // 写入全局参数，供页面层读取
            global.heartRateTimestamp = Date.now();   // 写入当前时间戳，用于做 30秒超时校验
        }
    } catch (e) {
        console.log(`Failed to get heart rate: ${e}`);
    }
}
