export default {
  private: {
    stage: 0,
    clockText: '--:--',
    hasData: false,
    pulseName: '--',
    pulseColor: '#8B7D6B',
    constName: '--',
    constDesc: '',
    dimRows: [],
    organRows: [],
    disclaimer: getText('pulse_theory_disclaimer'),
    // 4.0 兼容：chart 的 datasets 首帧不能为空数组（异步数据就绪前先给平线）
    waveData: [{ strokeColor: '#B0A176', data: getPulseShape('flat') }],
    waveOpts: {
      xAxis: { min: 0, max: 160, display: false },
      yAxis: { min: 0, max: 100, display: false },
      series: { lineStyle: { width: '4px' } }   // 文档要求 <length>，裸数字在轻量运行时可能是雷
    }
  },

  onInit() {
    console.log('[home] onInit: enter');
    this._hrvStorage = new HrvStorageManager();
    this._clockTimer = null;
    this._stageTimer = null;
    console.log('[home] onInit: storage constructed, calling _loadData');
    this._loadData();
    console.log('[home] onInit: exit');
  },

  onShow() {
    console.log('[home] onShow: enter, stage=' + this.stage);
    this._startClock();
    if (this._inited) this._loadData();
    this._startStaging();
    console.log('[home] onShow: exit');
  },

  onHide() {
    console.log('[home] onHide');
    if (this._clockTimer) { clearInterval(this._clockTimer); this._clockTimer = null; }
    if (this._stageTimer) { clearInterval(this._stageTimer); this._stageTimer = null; }
  },

  onDestroy() {
    console.log('[home] onDestroy');
    if (this._clockTimer) { clearInterval(this._clockTimer); this._clockTimer = null; }
    if (this._stageTimer) { clearInterval(this._stageTimer); this._stageTimer = null; }
  },

  // 阶段推进：每 800ms 挂载下一级控件，日志与屏上 S 徽标双通道留证
  // S1 文字骨架 → S2 体质卡 → S3 六维(for+progress) → S4 五脏 → S5 按钮组 → S6 chart
  _startStaging() {
    if (this.stage >= 6 || this._stageTimer) return;
    this._stageTimer = setInterval(() => {
      if (this.stage >= 6) {
        clearInterval(this._stageTimer);
        this._stageTimer = null;
        console.log('[home] staging complete: all widgets mounted OK');
        return;
      }
      this.stage = this.stage + 1;
      console.log('[home] stage -> S' + this.stage + ' mounted: ' + STAGE_DESC[this.stage]);
    }, 800);
  },

